module.exports = "<ng-template #container let-container=\"container\">\n  <div class=\"bmb_advertisement-card-container\">\n    <div\n      [ngClass]=\"{\n        'bmb_advertisement-card-content-image-full': expanded\n      }\"\n      class=\"bmb_advertisement-card-content-image\"\n    >\n      <figure class=\"bmb_advertisement-card-image-container-figure\">\n        <picture>\n          <source media=\"(min-width: 100px)\" [srcset]=\"container.imgData.url\" />\n          <img\n            [loading]=\"'lazy'\"\n            class=\"bmb_advertisement-card-image-container-figure-image\"\n            [srcset]=\"container.imgData.url\"\n            [alt]=\"container.imgData.alt\"\n          />\n        </picture>\n      </figure>\n    </div>\n    <section\n      [ngClass]=\"{\n        'bmb_advertisement-card-content-description-hide': !expanded\n      }\"\n      class=\"bmb_advertisement-card-content-description\"\n    >\n      <div class=\"bmb_advertisement-card-content-description-title\">\n        <h3>{{ container.content.title }}</h3>\n      </div>\n      <div class=\"bmb_advertisement-card-content-description-text\">\n        <p>{{ container.content.description }}</p>\n      </div>\n      <div class=\"bmb_advertisement-card-content-description-btn\">\n        <a\n          [href]=\"container.content.linkBtn\"\n          target=\"_blank\"\n          class=\"bmb_advertisement-card-content-description-btn-action\"\n          bmbButton\n          appearance=\"primary\"\n          size=\"small\"\n        >\n          {{ container.content.labelBtn }}\n        </a>\n      </div>\n    </section>\n  </div>\n</ng-template>\n\n<ng-template #tab let-tab=\"tab\">\n  <bmb-carousel>\n    @for (data of tab; track $index) {\n      <div #carouselItem>\n        <ng-container\n          *ngTemplateOutlet=\"container; context: { container: data }\"\n        />\n      </div>\n    }\n  </bmb-carousel>\n</ng-template>\n\n<div\n  class=\"bmb_advertisement-card\"\n  [ngClass]=\"{ 'bmb_advertisement-card-expanded': expanded }\"\n>\n  <bmb-home-card\n    leftIcon=\"chevron_left\"\n    icon=\"assignment\"\n    bgIconAppearance=\"mitec-green\"\n    [componentTitle]=\"componentTitle() || title() || ('advertisement_card.title' | translate)\"\n    [subtitle]=\"subtitle()\"\n    [(isExpanded)]=\"expanded\"\n    [useAutoExpand]=\"false\"\n  >\n    <div class=\"bmb_advertisement-card-tabs\">\n      <bmb-tabs\n        format=\"uppercase\"\n        [tabs]=\"tabsData\"\n        [(selectedTabId)]=\"selectedTabId\"\n      >\n        <section class=\"bmb_advertisement-card-content\">\n          @if (selectedTabId === 1) {\n            <ng-container\n              *ngTemplateOutlet=\"\n                tab;\n                context: { tab: this.data()?.promociones }\n              \"\n            />\n          }\n          @if (selectedTabId === 2) {\n            <ng-container\n              *ngTemplateOutlet=\"tab; context: { tab: this.data()?.avisos }\"\n            />\n          }\n          @if (selectedTabId === 3) {\n            <ng-container\n              *ngTemplateOutlet=\"\n                tab;\n                context: { tab: this.data()?.informacion }\n              \"\n            />\n          }\n        </section>\n      </bmb-tabs>\n    </div>\n  </bmb-home-card>\n</div>\n";

